KIND = "atlas"
SYSTEM = "muscular"
E = {
"m-sternocleidomastoideus": {
"en": ["Sternocleidomastoid", "A prominent muscle running obliquely across the side of the neck and dividing it into anterior and posterior triangles. It has two heads: sternal and clavicular.",
 ["Sternal head: front of the manubrium of the sternum; clavicular head: upper surface of the medial 1/3 of the clavicle",
  "Outer surface of the mastoid process and lateral half of the superior nuchal line", "Accessory nerve (XI) – motor; C2–C3 – proprioceptive",
  "Occipital, superior thyroid and suprascapular arteries",
  "One side: tilts the head to the same side and turns the face to the opposite side and upwards; both sides: flex the head forwards and, with the head fixed, raise the sternum as accessory muscles of respiration"], [],
 ["Injury or fibrosis of the muscle at birth causes congenital torticollis (wry neck).", "Accessory nerve injury weakens turning the head to the opposite side."],
 ["SCM divides the neck into anterior and posterior triangles; the accessory nerve emerges into the posterior triangle at the middle of its posterior border (near Erb's point).", "In congenital muscular torticollis the head tilts towards the lesion and the face turns to the opposite side."], ["SCM"]],
"fr": ["Muscle sterno-cléido-mastoïdien", "Muscle saillant qui croise obliquement la face latérale du cou et la divise en trigones antérieur et postérieur. Il a deux chefs : sternal et claviculaire.",
 ["Chef sternal : face antérieure du manubrium sternal ; chef claviculaire : face supérieure du 1/3 médial de la clavicule",
  "Face externe du processus mastoïde et moitié latérale de la ligne nucale supérieure", "Nerf accessoire (XI) – moteur ; C2–C3 – proprioceptif",
  "Artères occipitale, thyroïdienne supérieure et suprascapulaire",
  "Unilatéral : incline la tête du même côté et tourne la face du côté opposé et vers le haut ; bilatéral : fléchit la tête et, tête fixée, élève le sternum (muscle respiratoire accessoire)"], [],
 ["Une lésion ou une fibrose du muscle à la naissance entraîne un torticolis congénital.", "Une lésion du nerf accessoire affaiblit la rotation de la tête du côté opposé."],
 ["Le SCM divise le cou en trigones antérieur et postérieur ; le nerf accessoire sort dans le trigone postérieur au milieu de son bord postérieur (près du point d'Erb).", "Dans le torticolis musculaire congénital, la tête est inclinée du côté de la lésion et la face tournée du côté opposé."], ["SCM", "SCOM"]],
"de": ["M. sternocleidomastoideus", "Markanter Muskel, der schräg über die Halsseite zieht und den Hals in ein vorderes und ein seitliches Dreieck teilt. Er hat zwei Köpfe: Caput sternale und Caput claviculare.",
 ["Caput sternale: Vorderfläche des Manubrium sterni; Caput claviculare: Oberfläche des medialen Drittels der Clavicula",
  "Außenfläche des Processus mastoideus und laterale Hälfte der Linea nuchae superior", "N. accessorius (XI) – motorisch; C2–C3 – propriozeptiv",
  "A. occipitalis, A. thyroidea superior, A. suprascapularis",
  "Einseitig: neigt den Kopf zur gleichen Seite und dreht das Gesicht zur Gegenseite und nach oben; beidseitig: beugt den Kopf nach vorn und hebt bei fixiertem Kopf das Sternum (Atemhilfsmuskel)"], [],
 ["Eine Verletzung oder Fibrose des Muskels bei der Geburt führt zum angeborenen Schiefhals (Tortikollis).", "Eine Schädigung des N. accessorius schwächt die Kopfdrehung zur Gegenseite."],
 ["Der SCM teilt den Hals in vorderes und hinteres Dreieck; der N. accessorius tritt in der Mitte seines Hinterrands ins seitliche Halsdreieck (nahe dem Erb-Punkt).", "Beim angeborenen muskulären Schiefhals ist der Kopf zur kranken Seite geneigt und das Gesicht zur Gegenseite gedreht."], ["SCM", "Kopfnicker"]],
"es": ["Músculo esternocleidomastoideo", "Músculo prominente que cruza oblicuamente la cara lateral del cuello y lo divide en triángulos anterior y posterior. Tiene dos cabezas: esternal y clavicular.",
 ["Cabeza esternal: cara anterior del manubrio esternal; cabeza clavicular: cara superior del 1/3 medial de la clavícula",
  "Cara externa de la apófisis mastoides y mitad lateral de la línea nucal superior", "Nervio accesorio (XI) – motor; C2–C3 – propioceptivo",
  "Arterias occipital, tiroidea superior y supraescapular",
  "Unilateral: inclina la cabeza hacia el mismo lado y gira la cara al lado opuesto y hacia arriba; bilateral: flexiona la cabeza y, con la cabeza fija, eleva el esternón (músculo respiratorio accesorio)"], [],
 ["La lesión o fibrosis del músculo en el parto produce tortícolis congénita.", "La lesión del nervio accesorio debilita el giro de la cabeza hacia el lado opuesto."],
 ["El ECM divide el cuello en triángulos anterior y posterior; el nervio accesorio sale al triángulo posterior por la mitad de su borde posterior (cerca del punto de Erb).", "En la tortícolis muscular congénita la cabeza se inclina hacia el lado lesionado y la cara gira al opuesto."], ["ECM"]],
},
"mm-scaleni": {
"en": ["Scalene muscles", "Three muscles running from the transverse processes of the cervical vertebrae to the first two ribs. The brachial plexus and subclavian artery pass through the gap between the anterior and middle scalenes.",
 ["Tubercles of the transverse processes of C2–C7", "Anterior and middle: 1st rib (anterior scalene to the scalene tubercle); posterior: 2nd rib",
  "Anterior rami of the cervical nerves (C3–C8)", "Ascending cervical artery (inferior thyroid artery), transverse cervical artery",
  "Raise the first two ribs to assist inspiration; bend the neck to the same side"],
 [["Relations", "The phrenic nerve descends on the front of scalenus anterior. The subclavian vein passes in front of this muscle; the subclavian artery and brachial plexus pass behind it (through the scalene gap)."]],
 ["Compression in the scalene gap or a cervical rib can cause thoracic outlet syndrome (numbness of the arm, weak pulse).", "The interscalene block is used to anaesthetise the brachial plexus for shoulder surgery."],
 ["Scalenus anterior runs from the anterior tubercles of the C3–C6 transverse processes to the 1st rib; the phrenic nerve passes in front of it, the subclavian artery behind.", "The scalenes raise the 1st and 2nd ribs in forced inspiration."], ["scalene", "scalenus"]],
"fr": ["Muscles scalènes", "Trois muscles tendus des processus transverses des vertèbres cervicales aux deux premières côtes. Le plexus brachial et l'artère subclavière passent dans l'espace entre les scalènes antérieur et moyen.",
 ["Tubercules des processus transverses de C2–C7", "Antérieur et moyen : 1re côte (scalène antérieur au tubercule du scalène antérieur) ; postérieur : 2e côte",
  "Rameaux antérieurs des nerfs cervicaux (C3–C8)", "Artère cervicale ascendante (artère thyroïdienne inférieure), artère cervicale transverse",
  "Élèvent les deux premières côtes et aident l'inspiration ; inclinent le cou du même côté"],
 [["Rapports", "Le nerf phrénique descend sur la face antérieure du scalène antérieur. La veine subclavière passe en avant de ce muscle ; l'artère subclavière et le plexus brachial passent en arrière (défilé des scalènes)."]],
 ["Une compression dans le défilé des scalènes ou une côte cervicale peut provoquer un syndrome du défilé thoraco-brachial (engourdissement du bras, pouls faible).", "Le bloc interscalénique sert à anesthésier le plexus brachial en chirurgie de l'épaule."],
 ["Le scalène antérieur va des tubercules antérieurs des processus transverses de C3–C6 à la 1re côte ; le nerf phrénique passe en avant, l'artère subclavière en arrière.", "Les scalènes élèvent la 1re et la 2e côte lors de l'inspiration forcée."], ["scalène"]],
"de": ["Mm. scaleni", "Drei Muskeln von den Querfortsätzen der Halswirbel zu den ersten beiden Rippen. Durch die Lücke zwischen vorderem und mittlerem Skalenus ziehen Plexus brachialis und A. subclavia.",
 ["Tubercula der Querfortsätze C2–C7", "Anterior und medius: 1. Rippe (Scalenus anterior am Tuberculum musculi scaleni anterioris); posterior: 2. Rippe",
  "Rr. anteriores der Zervikalnerven (C3–C8)", "A. cervicalis ascendens (A. thyroidea inferior), A. transversa colli",
  "Heben die ersten beiden Rippen und unterstützen die Einatmung; neigen den Hals zur gleichen Seite"],
 [["Lagebeziehungen", "Der N. phrenicus zieht auf der Vorderfläche des M. scalenus anterior abwärts. Die V. subclavia verläuft vor diesem Muskel, A. subclavia und Plexus brachialis dahinter (durch die Skalenuslücke)."]],
 ["Eine Einengung der Skalenuslücke oder eine Halsrippe kann ein Thoracic-outlet-Syndrom verursachen (Taubheit des Arms, schwacher Puls).", "Die interskalenäre Blockade dient der Anästhesie des Plexus brachialis bei Schulteroperationen."],
 ["Der M. scalenus anterior zieht von den vorderen Höckern der Querfortsätze C3–C6 zur 1. Rippe; vor ihm verläuft der N. phrenicus, hinter ihm die A. subclavia.", "Die Skalenusmuskeln heben bei forcierter Einatmung die 1. und 2. Rippe."], ["Skalenus", "Treppenmuskeln"]],
"es": ["Músculos escalenos", "Tres músculos que van de las apófisis transversas de las vértebras cervicales a las dos primeras costillas. El plexo braquial y la arteria subclavia pasan por el hiato entre los escalenos anterior y medio.",
 ["Tubérculos de las apófisis transversas de C2–C7", "Anterior y medio: 1.ª costilla (escaleno anterior en el tubérculo del escaleno anterior); posterior: 2.ª costilla",
  "Ramos anteriores de los nervios cervicales (C3–C8)", "Arteria cervical ascendente (arteria tiroidea inferior), arteria cervical transversa",
  "Elevan las dos primeras costillas ayudando a la inspiración; inclinan el cuello hacia el mismo lado"],
 [["Relaciones", "El nervio frénico desciende sobre la cara anterior del escaleno anterior. La vena subclavia pasa por delante de este músculo; la arteria subclavia y el plexo braquial, por detrás (hiato de los escalenos)."]],
 ["La compresión en el hiato de los escalenos o una costilla cervical puede causar síndrome del desfiladero torácico (adormecimiento del brazo, pulso débil).", "El bloqueo interescalénico se usa para anestesiar el plexo braquial en la cirugía de hombro."],
 ["El escaleno anterior va de los tubérculos anteriores de las apófisis transversas C3–C6 a la 1.ª costilla; el frénico pasa por delante y la arteria subclavia por detrás.", "Los escalenos elevan la 1.ª y 2.ª costillas en la inspiración forzada."], ["escaleno"]],
},
"mm-suprahyoidei": {
"en": ["Suprahyoid muscles", "Four muscles above the hyoid bone that form the floor of the mouth: digastric, stylohyoid, mylohyoid and geniohyoid.",
 ["Digastric: posterior belly from the mastoid notch, anterior belly from the digastric fossa; stylohyoid: styloid process; mylohyoid: mylohyoid line; geniohyoid: inferior mental spine",
  "Hyoid bone (the intermediate tendon of digastric via a fibrous loop)",
  "Anterior belly of digastric and mylohyoid: nerve to mylohyoid (V3); posterior belly of digastric and stylohyoid: facial nerve (VII); geniohyoid: C1 (carried by the hypoglossal nerve)",
  "Submental artery (facial artery), lingual artery, occipital artery",
  "Raise the hyoid and larynx in swallowing; with the hyoid fixed they depress the mandible and open the mouth"], [], [],
 ["The suprahyoid muscles pull the hyoid and larynx upwards in swallowing and also help open the mouth.", "Mylohyoid forms the floor of the mouth (oral diaphragm); the submandibular gland wraps around its posterior border."], ["digastric", "mylohyoid"]],
"fr": ["Muscles suprahyoïdiens", "Quatre muscles situés au-dessus de l'os hyoïde qui forment le plancher de la bouche : digastrique, stylo-hyoïdien, mylo-hyoïdien et génio-hyoïdien.",
 ["Digastrique : ventre postérieur à l'incisure mastoïdienne, ventre antérieur à la fosse digastrique ; stylo-hyoïdien : processus styloïde ; mylo-hyoïdien : ligne mylo-hyoïdienne ; génio-hyoïdien : épine mentonnière inférieure",
  "Os hyoïde (tendon intermédiaire du digastrique par une boucle fibreuse)",
  "Ventre antérieur du digastrique et mylo-hyoïdien : nerf mylo-hyoïdien (V3) ; ventre postérieur et stylo-hyoïdien : nerf facial (VII) ; génio-hyoïdien : C1 (véhiculé par le nerf hypoglosse)",
  "Artère submentale (artère faciale), artère linguale, artère occipitale",
  "Élèvent l'os hyoïde et le larynx lors de la déglutition ; hyoïde fixé, abaissent la mandibule et ouvrent la bouche"], [], [],
 ["Les muscles suprahyoïdiens élèvent l'hyoïde et le larynx lors de la déglutition et participent à l'ouverture de la bouche.", "Le mylo-hyoïdien forme le plancher buccal (diaphragme oral) ; la glande submandibulaire contourne son bord postérieur."], ["digastrique", "mylo-hyoïdien"]],
"de": ["Obere Zungenbeinmuskeln", "Vier Muskeln oberhalb des Zungenbeins, die den Mundboden bilden: M. digastricus, M. stylohyoideus, M. mylohyoideus und M. geniohyoideus.",
 ["Digastricus: hinterer Bauch an der Incisura mastoidea, vorderer Bauch an der Fossa digastrica; Stylohyoideus: Processus styloideus; Mylohyoideus: Linea mylohyoidea; Geniohyoideus: Spina mentalis inferior",
  "Os hyoideum (Zwischensehne des Digastricus über eine Bindegewebsschlinge)",
  "Venter anterior des Digastricus und Mylohyoideus: N. mylohyoideus (V3); Venter posterior und Stylohyoideus: N. facialis (VII); Geniohyoideus: C1 (mit dem N. hypoglossus)",
  "A. submentalis (A. facialis), A. lingualis, A. occipitalis",
  "Heben beim Schlucken Zungenbein und Kehlkopf; bei fixiertem Zungenbein senken sie den Unterkiefer und öffnen den Mund"], [], [],
 ["Die suprahyoidalen Muskeln ziehen beim Schlucken Zungenbein und Kehlkopf nach oben und helfen bei der Mundöffnung.", "Der M. mylohyoideus bildet den Mundboden (Diaphragma oris); die Glandula submandibularis umgreift seinen Hinterrand."], ["Digastricus", "Mylohyoideus", "suprahyoidal"]],
"es": ["Músculos suprahioideos", "Cuatro músculos situados por encima del hioides que forman el suelo de la boca: digástrico, estilohioideo, milohioideo y genihioideo.",
 ["Digástrico: vientre posterior en la escotadura mastoidea, vientre anterior en la fosa digástrica; estilohioideo: apófisis estiloides; milohioideo: línea milohioidea; genihioideo: espina mentoniana inferior",
  "Hueso hioides (el tendón intermedio del digástrico mediante un asa fibrosa)",
  "Vientre anterior del digástrico y milohioideo: nervio milohioideo (V3); vientre posterior y estilohioideo: nervio facial (VII); genihioideo: C1 (vía el nervio hipogloso)",
  "Arteria submentoniana (arteria facial), arteria lingual, arteria occipital",
  "Elevan el hioides y la laringe al tragar; con el hioides fijo descienden la mandíbula y abren la boca"], [], [],
 ["Los suprahioideos elevan el hioides y la laringe al tragar y participan en la apertura de la boca.", "El milohioideo forma el suelo de la boca (diafragma oral); la glándula submandibular rodea su borde posterior."], ["digástrico", "milohioideo"]],
},
"mm-infrahyoidei": {
"en": ["Infrahyoid muscles", "Four strap-like muscles below the hyoid bone: sternohyoid, omohyoid, sternothyroid and thyrohyoid.",
 ["Sternohyoid and sternothyroid: back of the manubrium of the sternum; omohyoid (inferior belly): superior border of the scapula; thyrohyoid: oblique line of the thyroid cartilage",
  "Hyoid bone (sternothyroid: thyroid cartilage)", "Ansa cervicalis (C1–C3); thyrohyoid: C1 (with the hypoglossal nerve)", "Superior thyroid artery, lingual artery",
  "Pull down and steady the hyoid and larynx during swallowing and speech"], [],
 ["In thyroid surgery these muscles are retracted; the ansa cervicalis is preserved where possible."],
 ["The intermediate tendon of omohyoid crosses in front of the internal jugular vein and is anchored to the clavicle by a fascial sling.", "In thyroidectomy the infrahyoid ('strap') muscles are separated in the midline to expose the gland."], ["sternohyoid", "omohyoid", "strap muscles"]],
"fr": ["Muscles infrahyoïdiens", "Quatre muscles rubanés situés sous l'os hyoïde : sterno-hyoïdien, omo-hyoïdien, sterno-thyroïdien et thyro-hyoïdien.",
 ["Sterno-hyoïdien et sterno-thyroïdien : face postérieure du manubrium sternal ; omo-hyoïdien (ventre inférieur) : bord supérieur de la scapula ; thyro-hyoïdien : ligne oblique du cartilage thyroïde",
  "Os hyoïde (sterno-thyroïdien : cartilage thyroïde)", "Anse cervicale (C1–C3) ; thyro-hyoïdien : C1 (avec le nerf hypoglosse)", "Artère thyroïdienne supérieure, artère linguale",
  "Abaissent et stabilisent l'hyoïde et le larynx lors de la déglutition et de la parole"], [],
 ["En chirurgie thyroïdienne, ces muscles sont écartés ; on s'efforce de préserver l'anse cervicale."],
 ["Le tendon intermédiaire de l'omo-hyoïdien croise en avant la veine jugulaire interne et est amarré à la clavicule par une sangle fasciale.", "Lors de la thyroïdectomie, les muscles infrahyoïdiens sont séparés sur la ligne médiane pour exposer la glande."], ["sterno-hyoïdien", "omo-hyoïdien"]],
"de": ["Untere Zungenbeinmuskeln", "Vier bandförmige Muskeln unterhalb des Zungenbeins: M. sternohyoideus, M. omohyoideus, M. sternothyroideus und M. thyrohyoideus.",
 ["Sternohyoideus und Sternothyroideus: Rückfläche des Manubrium sterni; Omohyoideus (Venter inferior): Margo superior scapulae; Thyrohyoideus: Linea obliqua der Cartilago thyroidea",
  "Os hyoideum (Sternothyroideus: Cartilago thyroidea)", "Ansa cervicalis (C1–C3); Thyrohyoideus: C1 (mit dem N. hypoglossus)", "A. thyroidea superior, A. lingualis",
  "Ziehen Zungenbein und Kehlkopf beim Schlucken und Sprechen nach unten und fixieren sie"], [],
 ["Bei Schilddrüsenoperationen werden diese Muskeln zur Seite gehalten; die Ansa cervicalis wird möglichst geschont."],
 ["Die Zwischensehne des Omohyoideus kreuzt vor der V. jugularis interna und ist über eine Faszienschlinge an der Clavicula verankert.", "Bei der Thyreoidektomie werden die infrahyoidalen Muskeln in der Mittellinie getrennt, um die Drüse freizulegen."], ["Sternohyoideus", "Omohyoideus", "infrahyoidal"]],
"es": ["Músculos infrahioideos", "Cuatro músculos acintados situados debajo del hioides: esternohioideo, omohioideo, esternotiroideo y tirohioideo.",
 ["Esternohioideo y esternotiroideo: cara posterior del manubrio esternal; omohioideo (vientre inferior): borde superior de la escápula; tirohioideo: línea oblicua del cartílago tiroides",
  "Hueso hioides (esternotiroideo: cartílago tiroides)", "Asa cervical (C1–C3); tirohioideo: C1 (con el nervio hipogloso)", "Arteria tiroidea superior, arteria lingual",
  "Descienden y fijan el hioides y la laringe al tragar y hablar"], [],
 ["En la cirugía tiroidea estos músculos se separan; se procura conservar el asa cervical."],
 ["El tendón intermedio del omohioideo cruza por delante de la vena yugular interna y se ancla a la clavícula por una cincha fascial.", "En la tiroidectomía los infrahioideos se separan en la línea media para exponer la glándula."], ["esternohioideo", "omohioideo"]],
},
"mm-prevertebrales": {
"en": ["Prevertebral muscles", "Deep flexor muscles of the neck lying on the front of the cervical vertebrae.",
 ["Longus colli: vertebral bodies and transverse processes of C3–T3; longus capitis: transverse processes of C3–C6",
  "Longus colli: anterior tubercle of the atlas and upper cervical vertebrae; longus capitis: basilar part of the occipital bone",
  "Anterior rami of the cervical nerves (C1–C6)", "Vertebral artery, ascending cervical artery", "Flex the neck and head; support the cervical lordosis"], [],
 ["The deep neck flexors are often strained in whiplash injuries."],
 ["Longus colli and capitis flex the neck; they can be strained in whiplash injury.", "The 'danger space' between the prevertebral fascia and these muscles is a route by which infection can spread into the mediastinum."], ["longus colli", "longus capitis"]],
"fr": ["Muscles prévertébraux", "Muscles fléchisseurs profonds du cou situés à la face antérieure des vertèbres cervicales.",
 ["Long du cou : corps vertébraux et processus transverses de C3–T3 ; long de la tête : processus transverses de C3–C6",
  "Long du cou : tubercule antérieur de l'atlas et vertèbres cervicales hautes ; long de la tête : partie basilaire de l'os occipital",
  "Rameaux antérieurs des nerfs cervicaux (C1–C6)", "Artère vertébrale, artère cervicale ascendante", "Fléchissent le cou et la tête ; soutiennent la lordose cervicale"], [],
 ["Les fléchisseurs profonds du cou sont souvent sollicités dans le coup du lapin (whiplash)."],
 ["Les muscles long du cou et long de la tête fléchissent le cou ; ils peuvent être étirés dans le coup du lapin.", "L'« espace dangereux » entre le fascia prévertébral et ces muscles permet la diffusion d'une infection vers le médiastin."], ["long du cou", "long de la tête"]],
"de": ["Prävertebrale Muskeln", "Tiefe Beugemuskeln des Halses auf der Vorderfläche der Halswirbel.",
 ["Longus colli: Wirbelkörper und Querfortsätze C3–T3; Longus capitis: Querfortsätze C3–C6",
  "Longus colli: Tuberculum anterius atlantis und obere Halswirbel; Longus capitis: Pars basilaris des Os occipitale",
  "Rr. anteriores der Zervikalnerven (C1–C6)", "A. vertebralis, A. cervicalis ascendens", "Beugen Hals und Kopf; stützen die Halslordose"], [],
 ["Bei Schleudertraumen werden die tiefen Halsbeuger häufig überlastet."],
 ["Longus colli und capitis beugen den Hals; beim Schleudertrauma können sie gezerrt werden.", "Der „Danger Space“ zwischen Prävertebralfaszie und diesen Muskeln ist ein Weg, auf dem sich Infektionen ins Mediastinum ausbreiten können."], ["Longus colli", "Longus capitis"]],
"es": ["Músculos prevertebrales", "Músculos flexores profundos del cuello situados en la cara anterior de las vértebras cervicales.",
 ["Largo del cuello: cuerpos vertebrales y apófisis transversas de C3–T3; largo de la cabeza: apófisis transversas de C3–C6",
  "Largo del cuello: tubérculo anterior del atlas y vértebras cervicales altas; largo de la cabeza: porción basilar del occipital",
  "Ramos anteriores de los nervios cervicales (C1–C6)", "Arteria vertebral, arteria cervical ascendente", "Flexionan el cuello y la cabeza; sostienen la lordosis cervical"], [],
 ["Los flexores profundos del cuello se lesionan a menudo en el latigazo cervical."],
 ["El largo del cuello y el largo de la cabeza flexionan el cuello; pueden distenderse en el latigazo cervical.", "El «espacio peligroso» entre la fascia prevertebral y estos músculos es una vía por la que la infección puede extenderse al mediastino."], ["largo del cuello", "largo de la cabeza"]],
},
"m-trapezius": {
"en": ["Trapezius", "A broad superficial muscle over the upper back and back of the neck; together with its partner it forms a diamond (hood) shape. It has upper (descending), middle (transverse) and lower (ascending) parts.",
 ["Superior nuchal line, external occipital protuberance, nuchal ligament, spinous processes of C7–T12",
  "Lateral 1/3 of the clavicle, acromion and spine of the scapula", "Accessory nerve (XI) – motor; C3–C4 – sensory",
  "Transverse cervical artery (superficial cervical artery), suprascapular artery, occipital artery",
  "Upper fibres elevate the scapula (shrugging) and rotate it upwards; middle fibres retract it; lower fibres depress it and assist upward rotation"], [],
 ["If the accessory nerve is injured in the posterior triangle during cervical lymph node biopsy, the shoulder droops and the arm cannot be raised above 90°.", "The shoulder shrug test assesses the accessory nerve."],
 ["Trapezius: upper fibres elevate the scapula, middle fibres retract it, lower fibres depress it; upper and lower fibres together rotate it upwards.", "Its sensory (proprioceptive) fibres come from C3–C4; its motor nerve is the accessory nerve."], ["trapezius", "traps"]],
"fr": ["Muscle trapèze", "Large muscle superficiel de la partie haute du dos et de la nuque qui, avec son homologue, dessine un losange (capuchon). Il comporte des parties supérieure (descendante), moyenne (transverse) et inférieure (ascendante).",
 ["Ligne nucale supérieure, protubérance occipitale externe, ligament nucal, processus épineux de C7–T12",
  "1/3 latéral de la clavicule, acromion et épine de la scapula", "Nerf accessoire (XI) – moteur ; C3–C4 – sensitif",
  "Artère cervicale transverse (artère cervicale superficielle), artère suprascapulaire, artère occipitale",
  "Les fibres supérieures élèvent la scapula (haussement d'épaules) et la font tourner vers le haut ; les moyennes la rapprochent du rachis ; les inférieures l'abaissent et aident la rotation vers le haut"], [],
 ["Si le nerf accessoire est lésé dans le trigone postérieur lors d'une biopsie ganglionnaire cervicale, l'épaule tombe et le bras ne peut être élevé au-delà de 90°.", "Le test du haussement d'épaules évalue le nerf accessoire."],
 ["Trapèze : fibres supérieures élévatrices, moyennes adductrices, inférieures abaisseuses de la scapula ; supérieures et inférieures assurent ensemble la sonnette latérale.", "Ses fibres sensitives (proprioceptives) viennent de C3–C4 ; son nerf moteur est le nerf accessoire."], ["trapèze"]],
"de": ["M. trapezius", "Breiter oberflächlicher Muskel an oberem Rücken und Nacken, der mit dem der Gegenseite eine Rautenform (Kapuze) bildet. Er hat eine Pars descendens, transversa und ascendens.",
 ["Linea nuchae superior, Protuberantia occipitalis externa, Lig. nuchae, Dornfortsätze C7–T12",
  "Laterales Drittel der Clavicula, Acromion und Spina scapulae", "N. accessorius (XI) – motorisch; C3–C4 – sensibel",
  "A. transversa colli (A. cervicalis superficialis), A. suprascapularis, A. occipitalis",
  "Obere Fasern heben das Schulterblatt (Achselzucken) und drehen es nach oben; mittlere ziehen es zurück; untere senken es und unterstützen die Aufwärtsrotation"], [],
 ["Wird der N. accessorius bei einer Halslymphknotenbiopsie im seitlichen Halsdreieck verletzt, hängt die Schulter und der Arm kann nicht über 90° gehoben werden.", "Der Schulterhebetest prüft den N. accessorius."],
 ["Trapezius: obere Fasern heben, mittlere ziehen zurück, untere senken die Scapula; obere und untere Fasern rotieren sie gemeinsam nach oben.", "Seine sensiblen (propriozeptiven) Fasern stammen aus C3–C4; motorisch wird er vom N. accessorius versorgt."], ["Trapez", "Kapuzenmuskel"]],
"es": ["Músculo trapecio", "Músculo superficial ancho de la parte alta de la espalda y la nuca que, junto con el del otro lado, forma un rombo (capucha). Tiene porciones superior (descendente), media (transversa) e inferior (ascendente).",
 ["Línea nucal superior, protuberancia occipital externa, ligamento nucal, apófisis espinosas de C7–T12",
  "1/3 lateral de la clavícula, acromion y espina de la escápula", "Nervio accesorio (XI) – motor; C3–C4 – sensitivo",
  "Arteria cervical transversa (arteria cervical superficial), arteria supraescapular, arteria occipital",
  "Las fibras superiores elevan la escápula (encoger los hombros) y la rotan hacia arriba; las medias la retraen; las inferiores la descienden y ayudan a la rotación superior"], [],
 ["Si se lesiona el nervio accesorio en el triángulo posterior durante una biopsia ganglionar cervical, el hombro cae y el brazo no puede elevarse por encima de 90°.", "La prueba de encoger los hombros explora el nervio accesorio."],
 ["Trapecio: las fibras superiores elevan, las medias retraen y las inferiores descienden la escápula; superiores e inferiores juntas la rotan hacia arriba.", "Sus fibras sensitivas (propioceptivas) proceden de C3–C4; su nervio motor es el accesorio."], ["trapecio"]],
},
"m-latissimus-dorsi": {
"en": ["Latissimus dorsi", "The broadest muscle in the body, covering the lower and lateral back. It forms the posterior wall of the axilla.",
 ["Spinous processes of T7–L5, thoracolumbar fascia, posterior 1/3 of the iliac crest, lower 3–4 ribs, inferior angle of the scapula",
  "Floor of the intertubercular sulcus of the humerus", "Thoracodorsal nerve (C6–C8)", "Thoracodorsal artery (subscapular artery)",
  "Extends, adducts and internally rotates the arm (climbing, rowing); with the arm fixed it pulls the trunk upwards"], [],
 ["In breast reconstruction the muscle can be used as a flap together with its vascular pedicle.", "Thoracodorsal nerve injury during mastectomy weakens adduction and internal rotation of the arm."],
 ["Latissimus dorsi lifts the trunk when walking on crutches.", "In breast reconstruction the latissimus dorsi flap is raised on the thoracodorsal vessels."], ["lats", "latissimus"]],
"fr": ["Muscle grand dorsal", "Le muscle le plus large du corps, qui couvre la partie basse et latérale du dos. Il forme la paroi postérieure de l'aisselle.",
 ["Processus épineux de T7–L5, fascia thoraco-lombaire, 1/3 postérieur de la crête iliaque, 3–4 dernières côtes, angle inférieur de la scapula",
  "Fond du sillon intertuberculaire de l'humérus", "Nerf thoraco-dorsal (C6–C8)", "Artère thoraco-dorsale (artère subscapulaire)",
  "Porte le bras en extension, adduction et rotation médiale (grimper, ramer) ; bras fixé, il élève le tronc"], [],
 ["En reconstruction mammaire, le muscle peut être utilisé comme lambeau avec son pédicule vasculaire.", "Une lésion du nerf thoraco-dorsal lors d'une mastectomie affaiblit l'adduction et la rotation médiale du bras."],
 ["Le grand dorsal soulève le tronc lors de la marche avec des béquilles.", "En reconstruction mammaire, le lambeau de grand dorsal est prélevé sur les vaisseaux thoraco-dorsaux."], ["grand dorsal"]],
"de": ["M. latissimus dorsi", "Der flächengrößte Muskel des Körpers, der den unteren und seitlichen Rücken bedeckt. Er bildet die hintere Achselfalte.",
 ["Dornfortsätze T7–L5, Fascia thoracolumbalis, hinteres Drittel der Crista iliaca, untere 3–4 Rippen, Angulus inferior scapulae",
  "Boden des Sulcus intertubercularis humeri (Crista tuberculi minoris)", "N. thoracodorsalis (C6–C8)", "A. thoracodorsalis (A. subscapularis)",
  "Extension, Adduktion und Innenrotation des Arms (Klettern, Rudern); bei fixiertem Arm zieht er den Rumpf hoch"], [],
 ["Bei der Brustrekonstruktion kann der Muskel samt Gefäßstiel als Lappen verwendet werden.", "Eine Schädigung des N. thoracodorsalis bei der Mastektomie schwächt Adduktion und Innenrotation des Arms."],
 ["Der Latissimus dorsi hebt beim Gehen an Krücken den Rumpf an.", "Bei der Brustrekonstruktion wird der Latissimus-dorsi-Lappen an den thorakodorsalen Gefäßen gehoben."], ["Latissimus", "breiter Rückenmuskel"]],
"es": ["Músculo dorsal ancho", "El músculo más ancho del cuerpo, que cubre la parte baja y lateral de la espalda. Forma la pared posterior de la axila.",
 ["Apófisis espinosas de T7–L5, fascia toracolumbar, 1/3 posterior de la cresta ilíaca, 3–4 últimas costillas, ángulo inferior de la escápula",
  "Fondo del surco intertubercular del húmero", "Nervio toracodorsal (C6–C8)", "Arteria toracodorsal (arteria subescapular)",
  "Lleva el brazo a extensión, aducción y rotación interna (trepar, remar); con el brazo fijo eleva el tronco"], [],
 ["En la reconstrucción mamaria el músculo puede usarse como colgajo con su pedículo vascular.", "La lesión del nervio toracodorsal en la mastectomía debilita la aducción y la rotación interna del brazo."],
 ["El dorsal ancho eleva el tronco al caminar con muletas.", "En la reconstrucción mamaria el colgajo de dorsal ancho se levanta sobre los vasos toracodorsales."], ["dorsal ancho"]],
},
"mm-rhomboidei": {
"en": ["Rhomboid muscles", "Two muscles beneath trapezius running between the vertebral column and the medial border of the scapula.",
 ["Minor: lower part of the nuchal ligament, spinous processes of C7–T1; major: spinous processes of T2–T5",
  "Medial border of the scapula (minor at the level of the spine, major between the spine and the inferior angle)", "Dorsal scapular nerve (C4–C5)",
  "Dorsal scapular artery (deep branch of the transverse cervical artery)", "Retract, elevate and rotate the scapula downwards; hold the scapula against the chest wall"], [], [],
 ["In rhomboid palsy the medial border of the scapula drifts slightly outwards; it is tested by pressing the hands on the hips."], ["rhomboid"]],
"fr": ["Muscles rhomboïdes", "Deux muscles situés sous le trapèze, entre le rachis et le bord médial de la scapula.",
 ["Petit : partie basse du ligament nucal, processus épineux de C7–T1 ; grand : processus épineux de T2–T5",
  "Bord médial de la scapula (petit en regard de l'épine, grand entre l'épine et l'angle inférieur)", "Nerf dorsal de la scapula (C4–C5)",
  "Artère dorsale de la scapula (branche profonde de l'artère cervicale transverse)", "Rapprochent la scapula du rachis, l'élèvent et la font tourner vers le bas ; la plaquent contre le thorax"], [], [],
 ["Dans la paralysie des rhomboïdes, le bord médial de la scapula s'écarte légèrement ; on les teste en faisant appuyer les mains sur les hanches."], ["rhomboïde"]],
"de": ["Mm. rhomboidei", "Zwei Muskeln unter dem Trapezius zwischen Wirbelsäule und medialem Schulterblattrand.",
 ["Minor: unterer Teil des Lig. nuchae, Dornfortsätze C7–T1; major: Dornfortsätze T2–T5",
  "Margo medialis scapulae (minor auf Höhe der Spina, major zwischen Spina und Angulus inferior)", "N. dorsalis scapulae (C4–C5)",
  "A. dorsalis scapulae (tiefer Ast der A. transversa colli)", "Ziehen das Schulterblatt zurück, heben es und drehen es nach unten; halten es am Brustkorb"], [], [],
 ["Bei Rhomboideuslähmung weicht der mediale Schulterblattrand etwas nach außen ab; geprüft wird durch Druck der Hände gegen die Hüften."], ["Rhomboideus", "Rautenmuskeln"]],
"es": ["Músculos romboides", "Dos músculos bajo el trapecio que van entre la columna vertebral y el borde medial de la escápula.",
 ["Menor: parte inferior del ligamento nucal, apófisis espinosas de C7–T1; mayor: apófisis espinosas de T2–T5",
  "Borde medial de la escápula (menor a la altura de la espina, mayor entre la espina y el ángulo inferior)", "Nervio dorsal de la escápula (C4–C5)",
  "Arteria dorsal de la escápula (rama profunda de la cervical transversa)", "Retraen, elevan y rotan hacia abajo la escápula; la mantienen contra la pared torácica"], [], [],
 ["En la parálisis de los romboides el borde medial de la escápula se separa ligeramente; se exploran apretando las manos contra las caderas."], ["romboides"]],
},
"m-levator-scapulae": {
"en": ["Levator scapulae", "A muscle on the posterolateral neck running from the upper cervical vertebrae to the superior medial angle of the scapula.",
 ["Posterior tubercles of the transverse processes of C1–C4", "Upper part of the medial border of the scapula (between the superior angle and the spine)",
  "Dorsal scapular nerve (C5) and C3–C4 spinal nerves", "Dorsal scapular artery, transverse cervical artery", "Elevates the scapula and rotates it downwards; bends the neck to the same side"], [],
 ["Tension in this muscle is a common cause of neck pain and stiffness in desk workers."],
 ["Levator scapulae is a common cause of neck pain and torticollis; it is supplied by C3–C4 and the dorsal scapular nerve."], []],
"fr": ["Muscle élévateur de la scapula", "Muscle de la face postéro-latérale du cou tendu des vertèbres cervicales hautes à l'angle supéro-médial de la scapula.",
 ["Tubercules postérieurs des processus transverses de C1–C4", "Partie haute du bord médial de la scapula (entre l'angle supérieur et l'épine)",
  "Nerf dorsal de la scapula (C5) et nerfs spinaux C3–C4", "Artère dorsale de la scapula, artère cervicale transverse", "Élève la scapula et la fait tourner vers le bas ; incline le cou du même côté"], [],
 ["La tension de ce muscle est une cause fréquente de cervicalgie et de raideur chez les personnes travaillant assises."],
 ["L'élévateur de la scapula est une cause fréquente de cervicalgie et de torticolis ; il est innervé par C3–C4 et le nerf dorsal de la scapula."], ["angulaire de l'omoplate"]],
"de": ["M. levator scapulae", "Muskel am hinteren seitlichen Hals von den oberen Halswirbeln zum oberen inneren Schulterblattwinkel.",
 ["Tubercula posteriora der Querfortsätze C1–C4", "Oberer Teil des Margo medialis scapulae (zwischen Angulus superior und Spina)",
  "N. dorsalis scapulae (C5) und Spinalnerven C3–C4", "A. dorsalis scapulae, A. transversa colli", "Hebt das Schulterblatt und dreht es nach unten; neigt den Hals zur gleichen Seite"], [],
 ["Verspannungen dieses Muskels sind bei Büroarbeit eine häufige Ursache von Nackenschmerzen und -steife."],
 ["Der Levator scapulae ist eine häufige Ursache von Nackenschmerz und Schiefhals; innerviert von C3–C4 und N. dorsalis scapulae."], ["Schulterblattheber"]],
"es": ["Músculo elevador de la escápula", "Músculo de la cara posterolateral del cuello que va de las vértebras cervicales altas al ángulo superomedial de la escápula.",
 ["Tubérculos posteriores de las apófisis transversas de C1–C4", "Parte superior del borde medial de la escápula (entre el ángulo superior y la espina)",
  "Nervio dorsal de la escápula (C5) y nervios espinales C3–C4", "Arteria dorsal de la escápula, arteria cervical transversa", "Eleva la escápula y la rota hacia abajo; inclina el cuello hacia el mismo lado"], [],
 ["La tensión de este músculo es una causa frecuente de dolor y rigidez cervical en quienes trabajan sentados."],
 ["El elevador de la escápula es causa frecuente de cervicalgia y tortícolis; lo inervan C3–C4 y el nervio dorsal de la escápula."], ["angular del omóplato"]],
},
"mm-serrati-posteriores": {
"en": ["Serratus posterior muscles", "Thin muscles in the intermediate layer of the back that attach to the ribs; they play an accessory role in respiration.",
 ["Superior: nuchal ligament, spinous processes of C7–T3; inferior: spinous processes of T11–L2", "Superior: upper borders of ribs 2–5; inferior: lower borders of ribs 9–12",
  "Superior: intercostal nerves 2–5; inferior: intercostal nerves 9–11 and subcostal nerve", "Posterior intercostal arteries",
  "Superior raises the ribs, inferior pulls the ribs down (contributing to respiratory mechanics)"], [], [],
 ["Serratus posterior superior assists inspiration, the inferior assists expiration by pulling the ribs down; both are supplied by intercostal nerves."], []],
"fr": ["Muscles dentelés postérieurs", "Muscles minces de la couche intermédiaire du dos qui s'insèrent sur les côtes ; ils jouent un rôle accessoire dans la respiration.",
 ["Supérieur : ligament nucal, processus épineux de C7–T3 ; inférieur : processus épineux de T11–L2", "Supérieur : bord supérieur des côtes 2 à 5 ; inférieur : bord inférieur des côtes 9 à 12",
  "Supérieur : nerfs intercostaux 2 à 5 ; inférieur : nerfs intercostaux 9 à 11 et nerf subcostal", "Artères intercostales postérieures",
  "Le supérieur élève les côtes, l'inférieur les abaisse (contribution à la mécanique respiratoire)"], [], [],
 ["Le dentelé postérieur supérieur aide l'inspiration, l'inférieur l'expiration en abaissant les côtes ; tous deux sont innervés par des nerfs intercostaux."], []],
"de": ["Mm. serrati posteriores", "Dünne Muskeln der mittleren Rückenschicht, die an den Rippen ansetzen; sie unterstützen die Atmung.",
 ["Superior: Lig. nuchae, Dornfortsätze C7–T3; inferior: Dornfortsätze T11–L2", "Superior: Oberränder der 2.–5. Rippe; inferior: Unterränder der 9.–12. Rippe",
  "Superior: Nn. intercostales 2–5; inferior: Nn. intercostales 9–11 und N. subcostalis", "Aa. intercostales posteriores",
  "Superior hebt die Rippen, inferior zieht sie nach unten (Beitrag zur Atemmechanik)"], [], [],
 ["Der Serratus posterior superior unterstützt die Ein-, der inferior die Ausatmung durch Senken der Rippen; beide werden von Interkostalnerven innerviert."], ["Serratus posterior"]],
"es": ["Músculos serratos posteriores", "Músculos finos de la capa intermedia de la espalda que se insertan en las costillas; tienen un papel accesorio en la respiración.",
 ["Superior: ligamento nucal, apófisis espinosas de C7–T3; inferior: apófisis espinosas de T11–L2", "Superior: bordes superiores de las costillas 2.ª–5.ª; inferior: bordes inferiores de las costillas 9.ª–12.ª",
  "Superior: nervios intercostales 2.º–5.º; inferior: nervios intercostales 9.º–11.º y nervio subcostal", "Arterias intercostales posteriores",
  "El superior eleva las costillas y el inferior las desciende (contribuyen a la mecánica respiratoria)"], [], [],
 ["El serrato posterior superior ayuda a la inspiración y el inferior a la espiración al descender las costillas; ambos los inervan nervios intercostales."], []],
},
"m-erector-spinae": {
"en": ["Erector spinae", "The largest of the deep (intrinsic) back muscles, running along both sides of the vertebral column. From lateral to medial it consists of the iliocostalis, longissimus and spinalis columns.",
 ["Back of the sacrum, posterior iliac crest, lumbar spinous processes, sacrotuberous ligament and a common broad tendon",
  "Iliocostalis: angles of the ribs and transverse processes of the lower cervical vertebrae; longissimus: transverse processes, ribs and mastoid process; spinalis: upper spinous processes",
  "Posterior rami of the spinal nerves", "Posterior intercostal, lumbar and lateral sacral arteries",
  "Both sides: extend the spine and head (upright posture); one side: lateral flexion to the same side; works eccentrically to control forward bending"], [],
 ["Acute low back pain (lumbago) is often linked to spasm of this muscle group.", "Strengthening this muscle group is the basis of rehabilitation in chronic low back pain."],
 ["Erector spinae consists, from lateral to medial, of the iliocostalis, longissimus and spinalis columns ('I Love Spine').", "It controls forward bending of the trunk by eccentric contraction; spasm occurs in low back pain."], ["iliocostalis", "longissimus", "spinalis", "paraspinal muscles"]],
"fr": ["Muscle érecteur du rachis", "Le plus grand des muscles profonds (autochtones) du dos, situé de part et d'autre de la colonne vertébrale. De dehors en dedans, il comprend les colonnes ilio-costale, longissimus et épineuse.",
 ["Face postérieure du sacrum, partie postérieure de la crête iliaque, processus épineux lombaires, ligament sacro-tubéral et tendon commun large",
  "Ilio-costal : angles costaux et processus transverses des cervicales basses ; longissimus : processus transverses, côtes et processus mastoïde ; épineux : processus épineux supérieurs",
  "Rameaux postérieurs des nerfs spinaux", "Artères intercostales postérieures, lombaires et sacrales latérales",
  "Bilatéral : étend le rachis et la tête (station debout) ; unilatéral : inclinaison latérale homolatérale ; contrôle la flexion antérieure par contraction excentrique"], [],
 ["Le lumbago est souvent lié à un spasme de ce groupe musculaire.", "Le renforcement de ce groupe musculaire est la base de la rééducation des lombalgies chroniques."],
 ["L'érecteur du rachis comprend, de dehors en dedans, les colonnes ilio-costale, longissimus et épineuse.", "Il contrôle la flexion antérieure du tronc par contraction excentrique ; il se contracture dans les lombalgies."], ["ilio-costal", "longissimus", "épineux", "muscles paravertébraux"]],
"de": ["M. erector spinae", "Der größte der tiefen (autochthonen) Rückenmuskeln beiderseits der Wirbelsäule. Von lateral nach medial besteht er aus den Säulen M. iliocostalis, M. longissimus und M. spinalis.",
 ["Rückfläche des Kreuzbeins, hinterer Teil der Crista iliaca, lumbale Dornfortsätze, Lig. sacrotuberale und eine gemeinsame breite Sehne",
  "Iliocostalis: Rippenwinkel und Querfortsätze der unteren Halswirbel; Longissimus: Querfortsätze, Rippen und Processus mastoideus; Spinalis: obere Dornfortsätze",
  "Rr. posteriores der Spinalnerven", "Aa. intercostales posteriores, Aa. lumbales, Aa. sacrales laterales",
  "Beidseitig: Streckung von Wirbelsäule und Kopf (aufrechte Haltung); einseitig: Seitneigung zur gleichen Seite; kontrolliert das Vorbeugen exzentrisch"], [],
 ["Der Hexenschuss (Lumbago) hängt häufig mit einem Krampf dieser Muskelgruppe zusammen.", "Die Kräftigung dieser Muskelgruppe ist die Grundlage der Rehabilitation bei chronischen Rückenschmerzen."],
 ["Der Erector spinae besteht von lateral nach medial aus Iliocostalis, Longissimus und Spinalis.", "Er kontrolliert das Vorbeugen des Rumpfes exzentrisch; bei Rückenschmerz tritt ein Hartspann auf."], ["Iliocostalis", "Longissimus", "Spinalis", "Rückenstrecker"]],
"es": ["Músculo erector de la columna", "El mayor de los músculos profundos (intrínsecos) de la espalda, a ambos lados de la columna. De lateral a medial lo forman las columnas iliocostal, longísimo y espinoso.",
 ["Cara posterior del sacro, parte posterior de la cresta ilíaca, apófisis espinosas lumbares, ligamento sacrotuberoso y un tendón común ancho",
  "Iliocostal: ángulos costales y apófisis transversas de las cervicales bajas; longísimo: apófisis transversas, costillas y apófisis mastoides; espinoso: apófisis espinosas superiores",
  "Ramos posteriores de los nervios espinales", "Arterias intercostales posteriores, lumbares y sacras laterales",
  "Bilateral: extiende la columna y la cabeza (postura erguida); unilateral: flexión lateral al mismo lado; controla excéntricamente la flexión anterior"], [],
 ["El lumbago agudo se asocia a menudo con espasmo de este grupo muscular.", "Fortalecer este grupo muscular es la base de la rehabilitación del dolor lumbar crónico."],
 ["El erector de la columna está formado, de lateral a medial, por el iliocostal, el longísimo y el espinoso.", "Controla la flexión anterior del tronco por contracción excéntrica; en el dolor lumbar aparece espasmo."], ["iliocostal", "longísimo", "espinoso", "paravertebrales"]],
},
"mm-transversospinales": {
"en": ["Transversospinal muscles", "Deep back muscles running from the transverse processes of the vertebrae to the spinous processes above: semispinalis, multifidus and rotatores. Splenius and the short segmental muscles (interspinales, intertransversarii, levatores costarum) are also studied with this group.",
 ["Transverse processes of the vertebrae and the sacrum", "Spinous processes of higher vertebrae (semispinalis capitis to the occipital bone)",
  "Posterior rami of the spinal nerves", "Posterior intercostal, lumbar and occipital arteries",
  "Extend the spine and rotate it to the opposite side; provide segmental stability between vertebrae (especially multifidus)"], [],
 ["Atrophy of lumbar multifidus is associated with chronic low back pain."],
 ["Semispinalis, multifidus and rotatores belong to this group; multifidus is an important muscle for lumbar stability."], ["multifidus", "semispinalis", "rotatores", "splenius"]],
"fr": ["Muscles transversaires épineux", "Muscles profonds du dos tendus des processus transverses aux processus épineux sus-jacents : semi-épineux, multifides et rotateurs. Le splénius et les petits muscles segmentaires (interépineux, intertransversaires, élévateurs des côtes) sont étudiés avec ce groupe.",
 ["Processus transverses des vertèbres et sacrum", "Processus épineux des vertèbres sus-jacentes (semi-épineux de la tête sur l'os occipital)",
  "Rameaux postérieurs des nerfs spinaux", "Artères intercostales postérieures, lombaires et occipitale",
  "Étendent le rachis et le font tourner du côté opposé ; assurent la stabilité segmentaire (surtout le multifide)"], [],
 ["L'atrophie du multifide lombaire est associée à la lombalgie chronique."],
 ["Semi-épineux, multifides et rotateurs font partie de ce groupe ; le multifide est un muscle important de la stabilité lombaire."], ["multifide", "semi-épineux", "rotateurs", "splénius"]],
"de": ["Mm. transversospinales", "Tiefe Rückenmuskeln von den Querfortsätzen zu höher gelegenen Dornfortsätzen: M. semispinalis, Mm. multifidi und Mm. rotatores. Mit dieser Gruppe werden auch M. splenius und die kurzen Segmentmuskeln (Mm. interspinales, intertransversarii, levatores costarum) besprochen.",
 ["Querfortsätze der Wirbel und Kreuzbein", "Dornfortsätze höherer Wirbel (Semispinalis capitis am Os occipitale)",
  "Rr. posteriores der Spinalnerven", "Aa. intercostales posteriores, Aa. lumbales, A. occipitalis",
  "Strecken die Wirbelsäule und drehen sie zur Gegenseite; sorgen für segmentale Stabilität (v. a. Multifidus)"], [],
 ["Eine Atrophie des lumbalen Multifidus ist mit chronischen Rückenschmerzen verbunden."],
 ["Semispinalis, Multifidus und Rotatores gehören zu dieser Gruppe; der Multifidus ist ein wichtiger Muskel der lumbalen Stabilität."], ["Multifidus", "Semispinalis", "Rotatores", "Splenius"]],
"es": ["Músculos transversoespinosos", "Músculos profundos de la espalda que van de las apófisis transversas a las espinosas superiores: semiespinoso, multífidos y rotadores. Con este grupo se estudian también el esplenio y los músculos segmentarios cortos (interespinosos, intertransversos, elevadores de las costillas).",
 ["Apófisis transversas de las vértebras y sacro", "Apófisis espinosas de vértebras superiores (semiespinoso de la cabeza en el occipital)",
  "Ramos posteriores de los nervios espinales", "Arterias intercostales posteriores, lumbares y occipital",
  "Extienden la columna y la rotan al lado opuesto; dan estabilidad segmentaria entre vértebras (sobre todo el multífido)"], [],
 ["La atrofia del multífido lumbar se asocia con dolor lumbar crónico."],
 ["Semiespinoso, multífidos y rotadores forman este grupo; el multífido es un músculo importante de la estabilidad lumbar."], ["multífido", "semiespinoso", "rotadores", "esplenio"]],
},
"mm-suboccipitales": {
"en": ["Suboccipital muscles", "Four small muscles between the base of the skull and the first two cervical vertebrae: rectus capitis posterior major and minor, obliquus capitis superior and inferior.",
 ["Rectus major and obliquus inferior: spinous process of the axis; rectus minor: posterior tubercle of the atlas; obliquus superior: transverse process of the atlas",
  "Inferior nuchal line of the occipital bone (obliquus inferior to the transverse process of the atlas)", "Suboccipital nerve (posterior ramus of C1)",
  "Vertebral artery, occipital artery", "Extend the head and rotate it to the same side; make fine postural adjustments"],
 [["Suboccipital triangle", "The vertebral artery and suboccipital nerve lie in the floor of the triangle bounded by rectus capitis posterior major and obliquus capitis superior and inferior."]], [],
 ["The suboccipital muscles are supplied by the suboccipital nerve (posterior ramus of C1); C1 usually has no sensory branch.", "The greater occipital nerve (posterior ramus of C2) emerges at the lower border of the suboccipital triangle; it is involved in occipital neuralgia."], ["suboccipital"]],
"fr": ["Muscles sous-occipitaux", "Quatre petits muscles situés entre la base du crâne et les deux premières vertèbres cervicales : grand et petit droits postérieurs de la tête, obliques supérieur et inférieur de la tête.",
 ["Grand droit et oblique inférieur : processus épineux de l'axis ; petit droit : tubercule postérieur de l'atlas ; oblique supérieur : processus transverse de l'atlas",
  "Ligne nucale inférieure de l'os occipital (oblique inférieur sur le processus transverse de l'atlas)", "Nerf sous-occipital (rameau postérieur de C1)",
  "Artère vertébrale, artère occipitale", "Étendent la tête et la font tourner du même côté ; assurent les ajustements posturaux fins"],
 [["Triangle sous-occipital", "L'artère vertébrale et le nerf sous-occipital se trouvent au fond du triangle limité par le grand droit postérieur et les obliques supérieur et inférieur de la tête."]], [],
 ["Les muscles sous-occipitaux sont innervés par le nerf sous-occipital (rameau postérieur de C1) ; C1 n'a généralement pas de branche sensitive.", "Le grand nerf occipital (rameau postérieur de C2) émerge au bord inférieur du triangle sous-occipital ; il est en cause dans la névralgie d'Arnold."], ["sous-occipital"]],
"de": ["Subokzipitale Muskeln", "Vier kleine Muskeln zwischen Schädelbasis und den ersten beiden Halswirbeln: M. rectus capitis posterior major und minor, M. obliquus capitis superior und inferior.",
 ["Rectus major und Obliquus inferior: Dornfortsatz des Axis; Rectus minor: Tuberculum posterius atlantis; Obliquus superior: Querfortsatz des Atlas",
  "Linea nuchae inferior des Os occipitale (Obliquus inferior am Querfortsatz des Atlas)", "N. suboccipitalis (R. posterior von C1)",
  "A. vertebralis, A. occipitalis", "Strecken den Kopf und drehen ihn zur gleichen Seite; feine Haltungsanpassung"],
 [["Trigonum suboccipitale", "Im Boden des Dreiecks zwischen Rectus capitis posterior major, Obliquus capitis superior und inferior liegen A. vertebralis und N. suboccipitalis."]], [],
 ["Die subokzipitalen Muskeln werden vom N. suboccipitalis (R. posterior C1) innerviert; C1 hat meist keinen sensiblen Ast.", "Der N. occipitalis major (R. posterior C2) tritt am Unterrand des Trigonum suboccipitale hervor; er ist bei der Okzipitalneuralgie betroffen."], ["subokzipital", "Nackenmuskeln"]],
"es": ["Músculos suboccipitales", "Cuatro pequeños músculos entre la base del cráneo y las dos primeras vértebras cervicales: recto posterior mayor y menor de la cabeza, oblicuo superior e inferior de la cabeza.",
 ["Recto mayor y oblicuo inferior: apófisis espinosa del axis; recto menor: tubérculo posterior del atlas; oblicuo superior: apófisis transversa del atlas",
  "Línea nucal inferior del occipital (oblicuo inferior en la apófisis transversa del atlas)", "Nervio suboccipital (ramo posterior de C1)",
  "Arteria vertebral, arteria occipital", "Extienden la cabeza y la rotan hacia el mismo lado; realizan ajustes posturales finos"],
 [["Triángulo suboccipital", "En el suelo del triángulo formado por el recto posterior mayor y los oblicuos superior e inferior de la cabeza se encuentran la arteria vertebral y el nervio suboccipital."]], [],
 ["Los suboccipitales los inerva el nervio suboccipital (ramo posterior de C1); C1 no suele tener rama sensitiva.", "El nervio occipital mayor (ramo posterior de C2) sale por el borde inferior del triángulo suboccipital; se afecta en la neuralgia occipital."], ["suboccipital"]],
},
"m-pectoralis-major": {
"en": ["Pectoralis major", "A large fan-shaped muscle covering the upper front of the chest; it forms the anterior wall of the axilla. It has clavicular, sternocostal and abdominal parts.",
 ["Clavicular part: medial half of the clavicle; sternocostal part: sternum and costal cartilages 1–6; abdominal part: aponeurosis of the external oblique",
  "Crest of the greater tubercle of the humerus (lateral lip of the intertubercular sulcus)", "Medial (C8–T1) and lateral (C5–C7) pectoral nerves",
  "Pectoral branch of the thoraco-acromial artery, lateral thoracic artery, intercostal arteries",
  "Adducts and internally rotates the arm; the clavicular part flexes, the sternocostal part extends the flexed arm; with the arm fixed it pulls the trunk up (accessory muscle of respiration)"], [],
 ["In Poland syndrome the sternocostal part of the muscle is congenitally absent.", "In heavy lifting (bench press) its tendon can tear off the humerus."],
 ["Poland syndrome is the congenital absence of the sternocostal head of pectoralis major.", "The anterior axillary fold is formed by pectoralis major, the posterior fold by latissimus dorsi and teres major."], ["chest muscle", "pecs", "pectoral"]],
"fr": ["Muscle grand pectoral", "Grand muscle en éventail qui recouvre la partie antéro-supérieure du thorax ; il forme la paroi antérieure de l'aisselle. Il comporte des parties claviculaire, sterno-costale et abdominale.",
 ["Partie claviculaire : moitié médiale de la clavicule ; partie sterno-costale : sternum et cartilages costaux 1 à 6 ; partie abdominale : aponévrose de l'oblique externe",
  "Crête du tubercule majeur de l'humérus (lèvre latérale du sillon intertuberculaire)", "Nerfs pectoraux médial (C8–T1) et latéral (C5–C7)",
  "Rameau pectoral de l'artère thoraco-acromiale, artère thoracique latérale, artères intercostales",
  "Adduction et rotation médiale du bras ; la partie claviculaire fléchit, la partie sterno-costale étend le bras fléchi ; bras fixé, il élève le tronc (muscle respiratoire accessoire)"], [],
 ["Dans le syndrome de Poland, la partie sterno-costale du muscle est absente de naissance.", "Lors de charges lourdes (développé couché), son tendon peut s'arracher de l'humérus."],
 ["Le syndrome de Poland est l'absence congénitale du chef sterno-costal du grand pectoral.", "Le pli axillaire antérieur est formé par le grand pectoral, le postérieur par le grand dorsal et le grand rond."], ["pectoral", "pecs"]],
"de": ["M. pectoralis major", "Großer fächerförmiger Muskel an der oberen Vorderseite der Brust; er bildet die vordere Achselfalte. Er hat eine Pars clavicularis, sternocostalis und abdominalis.",
 ["Pars clavicularis: mediale Hälfte der Clavicula; Pars sternocostalis: Sternum und Rippenknorpel 1–6; Pars abdominalis: Aponeurose des M. obliquus externus",
  "Crista tuberculi majoris humeri (laterale Lippe des Sulcus intertubercularis)", "N. pectoralis medialis (C8–T1) und lateralis (C5–C7)",
  "R. pectoralis der A. thoracoacromialis, A. thoracica lateralis, Aa. intercostales",
  "Adduktion und Innenrotation des Arms; Pars clavicularis beugt, Pars sternocostalis streckt den gebeugten Arm; bei fixiertem Arm zieht er den Rumpf hoch (Atemhilfsmuskel)"], [],
 ["Beim Poland-Syndrom fehlt die Pars sternocostalis angeboren.", "Bei schwerem Heben (Bankdrücken) kann die Sehne vom Humerus abreißen."],
 ["Das Poland-Syndrom ist das angeborene Fehlen des sternokostalen Kopfes des Pectoralis major.", "Die vordere Achselfalte bildet der Pectoralis major, die hintere Latissimus dorsi und Teres major."], ["Brustmuskel", "Pectoralis"]],
"es": ["Músculo pectoral mayor", "Gran músculo en abanico que cubre la parte anterosuperior del tórax; forma la pared anterior de la axila. Tiene porciones clavicular, esternocostal y abdominal.",
 ["Porción clavicular: mitad medial de la clavícula; esternocostal: esternón y cartílagos costales 1.º–6.º; abdominal: aponeurosis del oblicuo externo",
  "Cresta del tubérculo mayor del húmero (labio lateral del surco intertubercular)", "Nervios pectorales medial (C8–T1) y lateral (C5–C7)",
  "Rama pectoral de la arteria toracoacromial, arteria torácica lateral, arterias intercostales",
  "Aduce y rota internamente el brazo; la porción clavicular flexiona y la esternocostal extiende el brazo flexionado; con el brazo fijo eleva el tronco (músculo respiratorio accesorio)"], [],
 ["En el síndrome de Poland falta de nacimiento la porción esternocostal del músculo.", "Al levantar cargas pesadas (press de banca) su tendón puede arrancarse del húmero."],
 ["El síndrome de Poland es la ausencia congénita de la cabeza esternocostal del pectoral mayor.", "El pliegue axilar anterior lo forma el pectoral mayor; el posterior, el dorsal ancho y el redondo mayor."], ["pectoral", "pecho"]],
},
}
